class Solution {
    public int minCost(String colors,int[] neededTime){
        int answer=0,kept=neededTime[0];
        for(int i=1;i<colors.length();i++)if(colors.charAt(i)==colors.charAt(i-1)){
            answer+=Math.min(kept,neededTime[i]);
            kept=Math.max(kept,neededTime[i]);
        }else kept=neededTime[i];
        return answer;
    }
}

code.kotlin:
class Solution {
    fun minCost(colors:String,neededTime:IntArray):Int{
        var answer=0;
        var kept=neededTime[0];
        for(i in 1 until colors.length)if(colors[i]==colors[i-1]){
            answer+=minOf(kept,neededTime[i]);
            kept=maxOf(kept,neededTime[i])
        }else kept=neededTime[i];
        return answer
    }
}

